import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) {
        InputReader in = new InputReader(System.in);
        OutputWriter out = new OutputWriter(System.out);
        _1047D solver = new _1047D();
        solver.solve(1, in, out);
        out.close();
    }

    static class _1047D {
        int n, m;

        public void solve(int testNumber, InputReader in, OutputWriter out) {
            n = in.nextInt();
            m = in.nextInt();

            long ans = 0;

            if (n > 100) {
                int nn = (n - 100) % 6;
                long nq = (n - 100) / 6;
                ans += nq * 6L * m;
                n = 100 + nn;
            }

            if (m > 100) {
                int nm = (m - 100) % 6;
                long mq = (m - 100) / 6;
                ans += mq * 6L * n;
                m = 100 + nm;
            }

            int[][] mat = new int[n + 1][m + 1];
            int u = 1, v = 1;

            for (int i = 1; i <= n; i++) {
                for (int j = 1; j <= m; j++) {
                    if ((i + j) % 2 == 0) mat[i][j] = u++;
                }
            }

            for (int i = 1; i <= n; i++) {
                for (int j = 1; j <= m; j++) {
                    if ((i + j) % 2 != 0) mat[i][j] = v++;
                }
            }

            List<Integer>[] g = new List[u];
            for (int i = 0; i < u; i++) g[i] = new ArrayList<>();

            int[] dx = {-3, -2, -2, 0, -1, 1, 0, -1, 1, 3, 2, 2};
            int[] dy = {0, -1, 1, -3, -2, -2, 3, 2, 2, 0, -1, 1};

            for (int x = 1; x <= n; x++) {
                for (int y = 1; y <= m; y++) {
                    if ((x + y) % 2 == 0) {
                        for (int k = 0; k < 12; k++) {
                            int nx = x + dx[k], ny = y + dy[k];
                            if (nx >= 1 && ny >= 1 && nx <= n && ny <= m) {
                                g[mat[x][y]].add(mat[nx][ny]);
                            }
                        }
                    }
                }
            }

            HopcroftKarpBipartiteMatching bpm = new HopcroftKarpBipartiteMatching(u - 1, v - 1, g);
            ans += 2L * bpm.maximumMatching();
            out.println(ans);
        }

        static class HopcroftKarpBipartiteMatching {
            final int m, n;
            final List<Integer>[] g;
            final int[] pairU, pairV, dis;
            final int inf = 10000000;
            final int NIL = 0;

            public HopcroftKarpBipartiteMatching(int m, int n, List<Integer>[] g) {
                this.m = m;
                this.n = n;
                this.g = g;
                this.pairU = new int[m + 1];
                this.pairV = new int[n + 1];
                this.dis = new int[m + 1];
            }

            int maximumMatching() {
                Arrays.fill(pairU, NIL);
                Arrays.fill(pairV, NIL);
                int maxMatching = 0;

                while (bfs()) {
                    for (int i = 1; i <= m; i++) {
                        if (pairU[i] == NIL && dfs(i)) {
                            maxMatching++;
                        }
                    }
                }
                return maxMatching;
            }

            boolean bfs() {
                Deque<Integer> q = new ArrayDeque<>();
                for (int i = 1; i <= m; i++) {
                    if (pairU[i] == NIL) {
                        q.addLast(i);
                        dis[i] = 0;
                    } else {
                        dis[i] = inf;
                    }
                }
                dis[NIL] = inf;

                while (!q.isEmpty()) {
                    int u = q.removeFirst();
                    if (dis[u] < dis[NIL]) {
                        for (int v : g[u]) {
                            if (dis[pairV[v]] == inf) {
                                q.addLast(pairV[v]);
                                dis[pairV[v]] = dis[u] + 2;
                            }
                        }
                    }
                }
                return dis[NIL] < inf;
            }

            boolean dfs(int u) {
                if (u != NIL) {
                    for (int v : g[u]) {
                        if (dis[pairV[v]] == dis[u] + 2) {
                            if (dfs(pairV[v])) {
                                pairV[v] = u;
                                pairU[u] = v;
                                return true;
                            }
                        }
                    }
                    dis[u] = inf;
                    return false;
                }
                return true;
            }
        }
    }

    static class InputReader {
        private final InputStream stream;
        private final byte[] buf = new byte[1024];
        private int curChar, numChars;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        public int read() {
            if (numChars == -1) throw new InputMismatchException();
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) return -1;
            }
            return buf[curChar++];
        }

        public int nextInt() {
            int c = read();
            while (isWhitespace(c)) c = read();
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') throw new InputMismatchException();
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isWhitespace(c));
            return res * sgn;
        }

        private boolean isWhitespace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }
    }

    static class OutputWriter {
        private final PrintWriter writer;

        public OutputWriter(OutputStream outputStream) {
            writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(outputStream)));
        }

        public void close() {
            writer.close();
        }

        public void println(long i) {
            writer.println(i);
        }
    }
}
